#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

run_wizard() {

TOTAL_STAGES=10
set +x
umask 077

if [[ ! -t 0 || ! -t 1 ]]; then
  printf '%s\n' 'Run this wizard directly in a terminal, without piping or recording input.' >&2
  exit 1
fi
if [[ "$(id -u)" == 0 ]]; then
  printf '%s\n' 'Run as your normal login user, not through sudo.' >&2
  exit 1
fi
case "$(uname -s)" in
  Darwin) BACKEND=darwin-keychain ;;
  Linux) BACKEND=linux-systemd-credentials ;;
  *) printf '%s\n' 'This migration supports Linux and macOS only.' >&2; exit 1 ;;
esac

PROJECT=$(cd -- "$(dirname -- "${BASH_SOURCE[0]}")/.." && pwd -P)
REPO=$(cd -- "$PROJECT/../.." && pwd -P)
if [[ "$PROJECT" != "$REPO/pub/secret_inject" || ! -d "$REPO/pub/dotfiles-nix" ]]; then
  warn 'Run this managed-host wizard from a full monorepo checkout, not the standalone CLI repo.'
  exit 1
fi
DOC="$PROJECT/docs/unattended-conformance.md"
STATE_DIR="${XDG_STATE_HOME:-$HOME/.local/state}/secret_inject/migration"
ENV_FILE="$STATE_DIR/choices.env"
ACTIVE_CONFIG="$HOME/.config/.secret_inject.json"
PYTHON=$(command -v python3) || { warn 'python3 is required.'; exit 1; }
command -v go >/dev/null 2>&1 || { warn 'Go is required.'; exit 1; }
[[ -f "$DOC" && -f "$PROJECT/go.mod" && -f "$PROJECT/cmd/secret_inject/main.go" ]] || {
  warn 'Required migration source files are missing from this checkout.'
  exit 1
}

verify_cached_export() {
  local binary="$1" config="$2" probe TIMEFORMAT
  probe=$(mktemp -d "$RUN_DIR/cache-check.XXXXXX")
  TIMEFORMAT='  Cache-only CLI invocation: %3R seconds'
  note 'Provider executables are unavailable on PATH during this check.'
  if { time PATH="$EMPTY_PATH" XDG_STATE_HOME="$probe" \
    "$binary" --config "$config" --profile shell --debug --output json >/dev/null; }; then
    :
  else
    warn 'Cache-only check failed: the snapshot may be missing/expired, or the store unavailable.'
    say 'No provider executable was available. Resolve the cause and rerun the warm-up.'
    return 1
  fi
  "$PYTHON" - "$probe/secret_inject/debug.log" <<'PY'
import json
import sys

try:
    with open(sys.argv[1], encoding="utf-8") as source:
        events = [json.loads(line) for line in source if line.strip()]
    hits = [event for event in events if event.get("kind") == "cache-state"]
    resolving = any(
        event.get("kind") == "provider-state"
        and event.get("operation") == "resolve"
        and event.get("state") == "started"
        for event in events
    )
    if len(hits) != 1 or hits[0].get("state") != "hit" or resolving:
        raise ValueError("not a clean cache hit")
except (OSError, ValueError, TypeError, AttributeError):
    raise SystemExit("Cache-hit verification failed; no log contents were displayed.")
print("  Verified: cache hit, no provider resolution started.")
PY
}

banner 'secret_inject: first private-credential migration'

stage 'Local readiness checks'
say 'This is a one-machine migration, not a release-certification runner.'
say 'It never commits, merges, activates Nix, or revokes vendor tokens for you.'
say 'Do not edit this source checkout while the wizard is running.'
warn 'Passing local tests does not certify native platforms or vendor releases.'
say 'Release certification is separate and does not block local setup.'
say "Release evidence requirements: $DOC"
confirm 'Run the ordinary Go 1.25 checks before changing live configuration?' || exit 1
if ! (cd -- "$PROJECT" && GOTOOLCHAIN=go1.25.0 go test -count=1 ./...); then
  warn 'STOPPED: local checks failed. No live configuration/store was changed.'
  say 'Resolve the build or test failures, then rerun this wizard.'
  exit 1
fi

stage 'Choose the personal or work configuration'
"$PYTHON" - "$STATE_DIR" "$ENV_FILE" <<'PY'
import os
import stat
import sys

root, env = sys.argv[1:]
if not os.path.isabs(root):
    raise SystemExit("Migration state directory must be absolute.")
parent = os.path.dirname(root)
os.makedirs(os.path.dirname(parent), mode=0o700, exist_ok=True)
for path, directory in ((parent, True), (root, True), (env, False)):
    if not os.path.lexists(path):
        if directory:
            os.mkdir(path, 0o700)
        else:
            continue
    info = os.lstat(path)
    kind_ok = stat.S_ISDIR(info.st_mode) if directory else stat.S_ISREG(info.st_mode)
    if not kind_ok or info.st_uid != os.getuid() or stat.S_IMODE(info.st_mode) & 0o077:
        raise SystemExit("Migration state must be owned, private, and not a symlink.")
PY
say 'Personal uses personal-doppler; work uses loancrate-doppler.'
say "This host uses the $BACKEND backend. Only choices/paths enter choices.env."
ask MIGRATION_SCOPE 'Type personal or work (Enter keeps a saved choice):'
case "$MIGRATION_SCOPE" in
  personal) ROOT_NAME=personal-doppler; DOPPLER_CONFIG=personal; ASSET=personal_secret_inject.json ;;
  work) ROOT_NAME=loancrate-doppler; DOPPLER_CONFIG=loancrate; ASSET=loancrate_secret_inject.json ;;
  *) warn 'Choose exactly personal or work, then rerun.'; exit 1 ;;
esac
write_env MIGRATION_SCOPE "$MIGRATION_SCOPE"
RUN_DIR=$(mktemp -d "$STATE_DIR/run.XXXXXX")
CFG="$RUN_DIR/native-config.json"
EMPTY_PATH="$RUN_DIR/no-provider-path"
mkdir -- "$EMPTY_PATH"
"$PYTHON" - "$REPO/pub/dotfiles-nix/mods/dotfiles/$ASSET" "$CFG" "$BACKEND" "$ROOT_NAME" "$DOPPLER_CONFIG" <<'PY'
import json
import os
import sys

source, destination, backend, root, environment = sys.argv[1:]
try:
    with open(source, encoding="utf-8") as stream:
        config = json.load(stream)
    doppler = config["sources"]["doppler"]
    if set(config["sources"]) != {"doppler"}:
        raise ValueError("unexpected source set")
    if doppler["project"] != "workstation_env_vars" or doppler["env"] != environment:
        raise ValueError("unexpected Doppler scope")
    if doppler["credential"] != {"kind": "stored", "name": root}:
        raise ValueError("unexpected credential binding")
    if config["profiles"]["shell"] != {"exclude": [], "overwrite": True}:
        raise ValueError("unexpected shell policy")
    if config["storage"] != {"type": "keyring", "allowed_backends": ["darwin-keychain", "linux-systemd-credentials"]}:
        raise ValueError("unexpected native backend allowlist")
    if backend not in config["storage"]["allowed_backends"]:
        raise ValueError("host backend is not allowed")
    with os.fdopen(os.open(destination, os.O_WRONLY | os.O_CREAT | os.O_EXCL, 0o600), "w") as stream:
        json.dump(config, stream, indent=2)
        stream.write("\n")
except (OSError, ValueError, KeyError, TypeError):
    raise SystemExit("Managed config shape changed; review the wizard before migrating.")
PY
say "Staged a private, platform-correct config: $CFG"
pause 'Press Enter to continue.'

stage 'Preserve the existing configuration privately'
LEGACY_BACKUP="$STATE_DIR/legacy-$MIGRATION_SCOPE.json"
say "Existing installed config: $ACTIVE_CONFIG"
say "Backup destination: $LEGACY_BACKUP"
warn 'An old config may contain a password. The backup is private and never printed.'
say 'An existing backup is kept, never replaced; no cache payload is imported.'
confirm 'Back up the installed config, or keep an existing backup?' || exit 1
"$PYTHON" - "$ACTIVE_CONFIG" "$LEGACY_BACKUP" <<'PY'
import os
import stat
import sys
import tempfile

source, destination = sys.argv[1:]
try:
    if os.path.lexists(destination):
        info = os.lstat(destination)
        if not stat.S_ISREG(info.st_mode) or info.st_uid != os.getuid() or stat.S_IMODE(info.st_mode) & 0o077:
            raise ValueError("unsafe backup")
        print("  Kept the existing private backup.")
    elif not os.path.lexists(source):
        print("  No installed config exists; no backup is necessary.")
    else:
        with open(source, "rb") as stream:
            if not stat.S_ISREG(os.fstat(stream.fileno()).st_mode):
                raise ValueError("not a regular config")
            data = stream.read(1024 * 1024 + 1)
        if len(data) > 1024 * 1024:
            raise ValueError("oversized config")
        descriptor, temporary = tempfile.mkstemp(prefix=".backup-", dir=os.path.dirname(destination))
        try:
            with os.fdopen(descriptor, "wb") as stream:
                stream.write(data)
                stream.flush()
                os.fsync(stream.fileno())
            os.link(temporary, destination)
        finally:
            os.unlink(temporary)
        print("  Saved the private config backup without displaying its contents.")
except (OSError, ValueError):
    raise SystemExit("Private config backup failed; no existing backup was overwritten.")
PY
write_env LEGACY_BACKUP "$LEGACY_BACKUP"
pause 'Press Enter to continue.'

stage 'Build an isolated candidate without replacing the installed CLI'
SI="$RUN_DIR/secret_inject"
say "Candidate output: $SI"
say 'The installed binary, working-tree binary, and active config stay unchanged.'
command -v doppler >/dev/null 2>&1 || {
  warn 'Install the Doppler CLI on PATH before enrolling.'
  exit 1
}
say 'Fresh fetches validate CLI version output and fail safely on unsupported commands.'
# The Makefile output is fixed; an isolated output avoids replacing that binary.
(cd -- "$PROJECT" && GOTOOLCHAIN=go1.25.0 go build -o "$SI" ./cmd/secret_inject)
chmod 700 "$SI"
"$SI" profile describe --config "$CFG" --profile shell >/dev/null
say 'Candidate built; config-only shell-profile validation passed.'
pause 'Press Enter to continue.'

stage 'Explicitly prepare the OS-native store'
say "Backend: $BACKEND."
if [[ "$BACKEND" == darwin-keychain ]]; then
  say 'Preparation may create/unlock the app keychain or ask OS approval.'
  warn 'Approve only the expected secret_inject native-store request.'
else
  say 'Preparation validates user-scoped systemd encryption and may initialize its host key.'
  say 'No graphical session or OS-password prompt is used; the host key is root-protected, not TPM-sealed.'
fi
say 'Ordinary shell startup never performs interactive recovery.'
confirm 'Allow explicit native-store preparation now?' || exit 1
"$SI" store prepare --config "$CFG" >/dev/null
say 'Native preparation succeeded.'
pause 'Press Enter to continue.'

stage 'Enroll or keep the provider-typed Doppler record'
"$SI" credential list --config "$CFG" >"$RUN_DIR/credential-metadata.json"
EXISTING=$("$PYTHON" - "$RUN_DIR/credential-metadata.json" "$ROOT_NAME" <<'PY'
import json
import sys

try:
    with open(sys.argv[1], encoding="utf-8") as stream:
        receipt = json.load(stream)
    if receipt["schema_version"] != 1:
        raise ValueError("unexpected metadata schema")
    matches = [item for item in receipt["credentials"] if item["name"] == sys.argv[2]]
    if len(matches) > 1 or any(item["provider"] != "doppler" for item in matches):
        raise ValueError("provider conflict")
    print("yes" if matches else "no")
except (OSError, ValueError, KeyError, TypeError):
    raise SystemExit("Credential metadata is invalid or the record has another provider.")
PY
)
ENROLL=yes
if [[ "$EXISTING" == yes ]]; then
  say "The $ROOT_NAME Doppler record already exists. Keeping it is the default."
  warn 'Replacing it invalidates ALL workload snapshots in this native store.'
  if ! confirm 'Replace the existing record with a token entered at the CLI prompt?'; then
    ENROLL=no
  fi
else
  say "No $ROOT_NAME record exists. A suitable config-scoped token is required."
  confirm 'Proceed to obtain and enroll a Doppler service token?' || exit 1
fi
if [[ "$ENROLL" == yes ]]; then
  open_url 'https://docs.doppler.com/docs/service-tokens'
  step "In Doppler, open project workstation_env_vars, then config $DOPPLER_CONFIG."
  step 'Access tab -> Generate -> name the token; leave optional write access OFF.'
  step 'Choose an expiration appropriate for ongoing shell use, not just this run.'
  step 'Generate Service Token -> copy it immediately; it is shown only once.'
  warn 'Do NOT paste it into wizard answers, chat, argv, .env, GitHub, or a pipe.'
  say 'Next, paste ONLY at the CLI prompt labelled Credential token (hidden).'
  confirm "Enroll/upsert $ROOT_NAME now, invalidating prior workload snapshots?" || exit 1
  # The CLI owns terminal input; the wizard must never capture or pipe the token.
  "$SI" credential set "$ROOT_NAME" --provider doppler --config "$CFG" >/dev/null
  say 'Enrollment succeeded. Clear the clipboard using your normal clipboard tool.'
fi
note 'Keep this enrolled token valid after migration; it is needed at later cache refreshes.'
pause 'Press Enter to continue.'

stage 'Fetch once, then prove two cache hits without provider executables'
say "The fresh fetch below contacts Doppler and replaces this scope's snapshot."
say 'All exported values go directly to /dev/null, never onto the terminal.'
warn 'Do not enable shell tracing or record terminal input.'
confirm 'Authorize one explicit fresh Doppler resolution to warm this scope?' || exit 1
"$SI" --config "$CFG" --profile shell --force --output json >/dev/null
verify_cached_export "$SI" "$CFG"
verify_cached_export "$SI" "$CFG"
say 'Both warm checks passed. Default TTL is one hour from the fetched snapshot.'
say 'Changing credentials, source scope, clearing cache, or TTL expiry causes a miss.'
pause 'Press Enter to continue to manual merge and activation.'

stage 'You merge the PR and activate from your normal checkout'
open_url 'https://github.com/pulls'
step 'If the implementation is not merged yet, review/commit/push it and open your monorepo PR.'
step 'Wait for passing CI, then merge; skip this if already merged.'
say 'This wizard does not stage, commit, push, merge, or pull any branch.'
confirm 'Has the PR been merged with the required checks passing?' || exit 1
step 'In another terminal, update your normal dotfiles/monorepo checkout to merged main.'
step 'Review it, then run your existing nixswitch function there.'
warn 'nixswitch uses the normal dotfiles checkout; running it here does not select this worktree.'
say 'Do not use nixswitchup as an implicit substitute for reviewing/pulling main.'
say 'If the cache expires while you do this, rerun this wizard to warm it again.'
confirm 'Has your normal nixswitch activation completed successfully?' || exit 1

stage 'Verify the activated config, binary, and fresh-shell startup'
say 'In the newly activated shell, run: command -v secret_inject'
say 'Paste only that absolute executable path below; never paste an environment dump.'
ask INSTALLED_CLI 'Absolute path printed by command -v secret_inject:'
[[ "$INSTALLED_CLI" == /* && -f "$INSTALLED_CLI" && -x "$INSTALLED_CLI" &&
   "$INSTALLED_CLI" != *$'\n'* && "$INSTALLED_CLI" != *$'\r'* ]] || {
  warn 'An absolute executable path is required.'; exit 1
}
if [[ "$INSTALLED_CLI" == "$RUN_DIR/"* ]]; then
  warn 'Choose the installed CLI, not the isolated candidate.'
  exit 1
fi
# Checking help first avoids invoking unknown verbs on a legacy CLI.
"$INSTALLED_CLI" --help >"$RUN_DIR/installed-help.txt" 2>&1
if ! grep -Fq 'credential set/list/remove' "$RUN_DIR/installed-help.txt"; then
  warn 'Installed CLI does not advertise the required credential command surface.'
  exit 1
fi
"$PYTHON" - "$CFG" "$ACTIVE_CONFIG" <<'PY'
import json
import sys

try:
    with open(sys.argv[1], encoding="utf-8") as stream:
        expected = json.load(stream)
    with open(sys.argv[2], encoding="utf-8") as stream:
        installed = json.load(stream)
    if installed != expected:
        raise ValueError("installed config differs")
except (OSError, ValueError, TypeError):
    raise SystemExit("Active config does not match the staged migration; review host selection/activation.")
print("  Active config matches the staged sources, binding, native backend, and profiles.")
PY
say 'Verify native-store readiness with the installed executable as well.'
if [[ "$BACKEND" == darwin-keychain ]]; then
  say 'Candidate approval may not transfer; preparation may show OS unlock and item-access dialogs.'
  say 'Approve only the expected installed CLI; choose Always Allow for its item-access prompts if offered.'
  say 'Enter the app-keychain password only in the OS dialog; values are never printed here.'
else
  say 'Systemd preparation uses the same user-scoped encrypted records without GUI or password prompts.'
fi
confirm 'Allow explicit native-store preparation with the installed CLI now?' || exit 1
"$INSTALLED_CLI" store prepare --config "$ACTIVE_CONFIG"
verify_cached_export "$INSTALLED_CLI" "$ACTIVE_CONFIG"
write_env INSTALLED_CLI "$INSTALLED_CLI"
step 'Open two fresh terminal shells using the default shell profile.'
step 'Check startup succeeds, with no token/OS prompt or secret_inject error.'
say 'Do not print env, export -p, or the generated export text to diagnose it.'
confirm 'Did both fresh shells start successfully without unexpected prompting?' || exit 1

stage 'Optional legacy-cache cleanup and ambient-copy review'
say 'Review obsolete token exports in shell startup, dotenv, and ordinary provider output.'
say 'Remove only obsolete copies intentionally; exclusions do not unset parent variables.'
warn 'A remaining parent DOPPLER_TOKEN can still reach targets through full inheritance.'
say 'No token rotation/revocation is automatic. Do not revoke the enrolled token.'
LEGACY_KIND=$("$PYTHON" - "$LEGACY_BACKUP" <<'PY'
import json
import os
import sys

path = sys.argv[1]
if not os.path.exists(path):
    print("none")
    raise SystemExit(0)
try:
    with open(path, encoding="utf-8") as stream:
        storage = json.load(stream).get("storage") or {}
    legacy = storage.get("type") == "file" or (
        storage.get("type") == "keyring" and storage.get("allowed_backends") == ["file"]
    )
    print("legacy" if legacy else "other")
except (OSError, ValueError, AttributeError, TypeError):
    raise SystemExit("Cannot safely classify the saved config for legacy cleanup.")
PY
)
if [[ "$LEGACY_KIND" == legacy ]]; then
  say "Cleanup uses the saved legacy config: $LEGACY_BACKUP"
  warn 'Deletion is irreversible; it removes owned legacy cache entries, not vendor tokens.'
  say 'It cannot import/decode the old cache and does not delete enrolled native roots.'
  if confirm 'Delete the owned legacy cache entries now?'; then
    "$SI" --config "$LEGACY_BACKUP" --clean >/dev/null
    say 'Legacy cache cleanup succeeded.'
  else
    SKIPPED+=('Legacy cache deletion was deliberately skipped; private backup retained.')
  fi
else
  note 'No supported legacy file-cache backup was found; no cache is deleted.'
fi
pause 'Finish reviewing obsolete copies; press Enter for the summary.'

finish
say "Migrated scope: $MIGRATION_SCOPE; native record: $ROOT_NAME ($BACKEND)."
say 'Verified the candidate and installed CLI use a warm snapshot without provider lookup.'
say 'No provider token was captured as a wizard answer or written to choices.env/GitHub.'
say "Private state and backup retained: $STATE_DIR"
say 'Remove this temporary helper from the repository after all hosts migrate; keep backups private.'
say 'Future refreshes still need a valid enrolled token and a prepared/unlocked native store.'
}

run_wizard "$@"; exit
